// Product-owned mock wire reused from channel/email/capture.mjs, no SDK stub here.
import net from 'node:net';
export async function startEmail(generation,rows,sockets,mailText){
 const wire={push:event=>rows.push({mailWire:event})},mail={push:event=>rows.push({mailSent:event})};
 const messages=[{uid:1,from:'old@example.test',raw:'old primed message'}];
 const track=s=>{sockets.add(s);s.on('error',()=>{});s.on('close',()=>sockets.delete(s));};
const imap=net.createServer(s=>{track(s);s.write('* OK owned mock\r\n');let buf='';s.on('data',b=>{buf+=b;for(;;){let at=buf.indexOf('\r\n');if(at<0)break;let line=buf.slice(0,at);buf=buf.slice(at+2);wire.push({protocol:'imap',line});let[tag,cmd,...parts]=line.split(' ');cmd=cmd.toUpperCase();if(cmd==='LOGIN')s.write(tag+' OK login\r\n');else if(cmd==='SELECT')s.write('* '+messages.length+' EXISTS\r\n* OK [UIDVALIDITY 1] valid\r\n* OK [UIDNEXT '+(messages.at(-1).uid+1)+'] next\r\n'+tag+' OK [READ-WRITE] selected\r\n');else if(cmd==='STATUS')s.write('* STATUS INBOX (UIDNEXT '+(messages.at(-1).uid+1)+')\r\n'+tag+' OK status\r\n');else if(cmd==='SEARCH'){const uid=generation()+2;if(!messages.some(m=>m.uid===uid))messages.push({uid,from:'human@example.test',raw:'Content-Type: text/plain\r\n\r\n'+mailText()});s.write('* SEARCH '+messages.map((_,i)=>i+1).join(' ')+'\r\n'+tag+' OK search\r\n');}else if(cmd==='FETCH'){let range=parts[0],all=parts.slice(1).join(' '),indexes=range.includes(':')?(()=>{const[a,b]=range.split(':').map(Number);return Array.from({length:Math.max(0,b-a+1)},(_,i)=>a+i)})():range.split(',').map(Number);for(const i of indexes){const m=messages[i-1];if(!m)continue;if(!all.includes('BODY')){s.write('* '+i+' FETCH (UID '+m.uid+')\r\n');continue}let[user,host]=m.from.split('@');s.write('* '+i+' FETCH (UID '+m.uid+' ENVELOPE (NIL "Message" ((NIL NIL "'+user+'" "'+host+'")) NIL NIL NIL NIL NIL NIL NIL) BODY[] {'+Buffer.byteLength(m.raw)+'}\r\n'+m.raw+')\r\n');}s.write(tag+' OK fetch\r\n');}else if(cmd==='LOGOUT'){s.write('* BYE logout\r\n'+tag+' OK logout\r\n');s.end();}else if(cmd==='CAPABILITY')s.write('* CAPABILITY IMAP4rev1\r\n'+tag+' OK cap\r\n');else s.write(tag+' BAD unsupported\r\n');}});});
const smtp=net.createServer(s=>{track(s);s.write('220 owned mock\r\n');let buf='',data=false,body='',from='',to='';s.on('data',b=>{buf+=b;for(;;){let at=buf.indexOf('\r\n');if(at<0)break;let line=buf.slice(0,at);buf=buf.slice(at+2);if(data){if(line==='.') {data=false;let[head,...rest]=body.split('\r\n\r\n');let subject=head.split('\r\n').find(s=>/^subject:/i.test(s))?.replace(/^subject:\s*/i,'')??'';let text=rest.join('\r\n\r\n').replace(/\r\n$/,'');if(/content-transfer-encoding:\s*base64/i.test(head))text=Buffer.from(text.replace(/\s/g,''),'base64').toString('utf8');else if(/content-transfer-encoding:\s*quoted-printable/i.test(head)){const folded=text.replace(/=\r\n/g,'');const bytes=[];for(let i=0;i<folded.length;i++){if(folded[i]==='='&&/^[0-9a-f]{2}$/i.test(folded.slice(i+1,i+3))){bytes.push(parseInt(folded.slice(i+1,i+3),16));i+=2;}else bytes.push(...Buffer.from(folded[i]));}text=Buffer.from(bytes).toString('utf8');}mail.push({from,to,subject,text});s.write(text==='FAIL'?'550 owned fail\r\n':'250 queued\r\n');body='';}else body+=(line.startsWith('..')?line.slice(1):line)+'\r\n';continue}wire.push({protocol:'smtp',line});let cmd=line.split(' ')[0].toUpperCase();if(cmd==='EHLO')s.write('250-owned\r\n250-AUTH PLAIN LOGIN\r\n250 8BITMIME\r\n');else if(cmd==='AUTH')s.write('235 authenticated\r\n');else if(cmd==='MAIL'){from=line.match(/<([^>]+)>/)[1];s.write('250 sender\r\n');}else if(cmd==='RCPT'){to=line.match(/<([^>]+)>/)[1];s.write('250 recipient\r\n');}else if(cmd==='DATA'){data=true;s.write('354 data\r\n');}else if(cmd==='QUIT'){s.write('221 bye\r\n');s.end();}else s.write('250 ok\r\n');}});});
 await Promise.all([new Promise(r=>imap.listen(0,'127.0.0.1',r)),new Promise(r=>smtp.listen(0,'127.0.0.1',r))]);
 return {imap,smtp,config:'      address: bot@example.test\n      password: mock-only\n      imapHost: 127.0.0.1\n      smtpHost: 127.0.0.1\n      imapPort: '+imap.address().port+'\n      smtpPort: '+smtp.address().port+'\n      imapTls: false\n      smtpTls: false\n      pollIntervalMs: 100\n'};
}
